// Generated by `just generate` from `src/plugins/claudetto-sessions/slices/usage/domain/versions.ts`. Edit the source and run `just generate`.
// The plugin version record: the version of this plugin in each session, by session id.
// The `session.start` hook adds each session to it in `$.store`, and the usage report counts the sessions of the period by it.

import { rethrowUnless } from "../../../kernel/errors.ts";

/** The record: the plugin version by session id, the oldest session first. */
export type VersionRecord = Record<string, string>;

/** The record in `value`, or an empty record when `value` is not one. A value of another form is dropped. */
export const recordOf = (value: unknown): VersionRecord => {
  if (typeof value !== "object" || value === null || Array.isArray(value))
    return {};
  return Object.fromEntries(
    Object.entries(value).filter(
      (entry): entry is [string, string] => typeof entry[1] === "string",
    ),
  );
};

/** The record with session `id` at `version`, as the newest entry, with at most `max` sessions. */
export const withSession = (
  record: VersionRecord,
  id: string,
  version: string,
  max: number,
): VersionRecord => {
  const entries = Object.entries(record).filter(([key]) => key !== id);
  entries.push([id, version]);
  return Object.fromEntries(entries.slice(-max));
};

/** The version in the text of a `plugin.json` manifest, or "unknown". */
export const manifestVersion = (text: string): string => {
  try {
    const version = (JSON.parse(text) as { version?: unknown }).version;
    return typeof version === "string" ? version : "unknown";
  } catch (err) {
    rethrowUnless(err, "SyntaxError");
    return "unknown";
  }
};
